const b: number = 7;
console.log(a + b);

const a: number = 17;
const b: number = 5;
console.log(Math.floor(a / b), a % b);

const name: string = "Анна";
const age: number = 25;
console.log(`Меня зовут ${name}, мне ${age}`);

const width: number = 6;
const height: number = 4;
console.log(width * height);

const a: number = 10;
if (a > 0) {
  console.log("положительное");
} else {
  console.log("отрицательное");
}

const n: number = 8;
if (n % 2 === 0) {
  console.log("чётное");
} else {
  console.log("нечётное");
}

const a: number = 3, b: number = 9, c: number = 5;
if (a >= b && a >= c) console.log(a);
else if (b >= c) console.log(b);
else console.log(c);

const day: number = 3;
if (day === 1) console.log("понедельник");
else if (day === 2) console.log("вторник");
else if (day === 3) console.log("среда");
else console.log("другой день");

let total: number = 0;
for (let i = 1; i <= 10; i++) total += i;
console.log(total);

const table: number[] = [];
for (let i = 1; i <= 10; i++) table.push(i * 3);
console.log(table.join(" "));

const n: number = 5;
let fact: number = 1;
for (let i = 1; i <= n; i++) fact *= i;
console.log(fact);

let n: number = 456;
let total: number = 0;
while (n > 0) {
  total += n % 10;
  n = Math.floor(n / 10);
}
console.log(total);

const s: string = "программирование";
const vowels: string = "аеёиоуыэюя";
let count: number = 0;
for (const ch of s) if (vowels.includes(ch)) count++;
console.log(count);

const nums: number[] = [4, 8, 15, 16, 23, 42];
let best: number = nums[0];
for (const n of nums) if (n > best) best = n;
console.log(best);

const nums: number[] = [4, 8, 15, 16, 23, 42];
let best: number = nums[0];
for (const n of nums) if (n < best) best = n;
console.log(best);

function add(a: number, b: number): number {
  return a + b;
}

console.log(add(3, 4));

function fact(n: number): number {
  let result: number = 1;
  for (let i = 1; i <= n; i++) result *= i;
  return result;
}

console.log(fact(5));

const n: number = 7;
let a: number = 0, b: number = 1;
const result: number[] = [];
for (let i = 0; i < n; i++) {
  result.push(a);
  [a, b] = [b, a + b];
}
console.log(result.join(" "));

const n: number = 17;
let isPrime: boolean = n > 1;
for (let d = 2; d * d <= n; d++) {
  if (n % d === 0) { isPrime = false; break; }
}
console.log(isPrime ? "простое" : "составное");

let a: number = 5;
let b: number = 7;
[a, b] = [b, a];
console.log(a, b);

const a: number = 3, b: number = 4, op: string = "*";
let result: number;
switch (op) {
  case "+": result = a + b; break;
  case "-": result = a - b; break;
  case "*": result = a * b; break;
  default: result = a / b;
}
console.log(result);

